import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { CheckCircle2, Circle, ChevronRight, Users, Rocket, ExternalLink } from "lucide-react";

const STORAGE = "threatlens-onboarding-progress";

type Step = {
  id: string;
  title: string;
  description: string;
  link?: string;
  linkLabel?: string;
};

const STEPS: Step[] = [
  { id: "auth", title: "Configure authentication", description: "Set up Supabase auth, allowlist users, and admin email in env.", link: "/admin", linkLabel: "Admin console" },
  { id: "feeds", title: "Enable threat feeds", description: "Verify fetch-feeds cron and source health; confirm live feed populates.", link: "/feed", linkLabel: "Live feed" },
  { id: "soc", title: "SOC workstation setup", description: "Configure cases, playbooks, and automations for your tier-1 team.", link: "/soc", linkLabel: "SOC dashboard" },
  { id: "intel", title: "Threat intel baseline", description: "Review dashboard, IOC lookup, and AI brief generation.", link: "/", linkLabel: "CTI dashboard" },
  { id: "api", title: "API & integrations", description: "Issue API keys and connect SIEM/SOAR via API portal.", link: "/api-portal", linkLabel: "API portal" },
  { id: "clients", title: "Client engagements", description: "Create client records and assign analysts.", link: "/clients", linkLabel: "Client management" },
  { id: "kb", title: "Knowledge base & runbooks", description: "Publish internal runbooks for your SOC playbooks.", link: "/knowledge", linkLabel: "Knowledge base" },
  { id: "metrics", title: "Executive reporting", description: "Configure CISO brief and security metrics for leadership.", link: "/ciso-brief", linkLabel: "CISO brief" },
];

function loadProgress(): Record<string, boolean> {
  try {
    const raw = localStorage.getItem(STORAGE);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

export default function CustomerOnboarding() {
  const [done, setDone] = useState<Record<string, boolean>>(loadProgress);

  useEffect(() => {
    localStorage.setItem(STORAGE, JSON.stringify(done));
  }, [done]);

  const completed = STEPS.filter((s) => done[s.id]).length;
  const pct = Math.round((completed / STEPS.length) * 100);

  const toggle = (id: string) => setDone((d) => ({ ...d, [id]: !d[id] }));

  return (
    <div className="container mx-auto px-4 py-8 max-w-4xl">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
        <ChevronRight className="h-3 w-3" />
        <Link to="/company/customer-success" className="hover:text-cyan-400">Customer Success</Link>
        <ChevronRight className="h-3 w-3" />
        <span className="text-teal-400">Onboarding Hub</span>
      </div>

      <div className="flex items-start gap-4 mb-8">
        <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-teal-500 to-emerald-600">
          <Rocket className="h-6 w-6 text-white" />
        </div>
        <div className="flex-1">
          <h1 className="text-2xl font-bold">Customer Onboarding Hub</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Guided deployment checklist for CSEs and solutions engineers
          </p>
          <div className="mt-4 flex items-center gap-4">
            <Progress value={pct} className="flex-1 h-2" />
            <Badge variant="outline" className="shrink-0">{completed}/{STEPS.length} complete</Badge>
          </div>
        </div>
      </div>

      <div className="space-y-3">
        {STEPS.map((step, i) => {
          const isDone = !!done[step.id];
          return (
            <Card key={step.id} className={isDone ? "border-emerald-500/20 bg-emerald-500/5" : ""}>
              <CardContent className="py-4 flex items-start gap-4">
                <button type="button" onClick={() => toggle(step.id)} className="mt-0.5 shrink-0">
                  {isDone ? (
                    <CheckCircle2 className="h-6 w-6 text-emerald-400" />
                  ) : (
                    <Circle className="h-6 w-6 text-slate-600 hover:text-cyan-400" />
                  )}
                </button>
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-muted-foreground">Step {i + 1}</p>
                  <p className="font-medium">{step.title}</p>
                  <p className="text-sm text-muted-foreground mt-0.5">{step.description}</p>
                  {step.link && (
                    <Button variant="link" size="sm" className="px-0 h-auto mt-1" asChild>
                      <Link to={step.link}>
                        {step.linkLabel} <ExternalLink className="h-3 w-3 ml-1 inline" />
                      </Link>
                    </Button>
                  )}
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      <Card className="mt-8 border-teal-500/20">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm flex items-center gap-2">
            <Users className="h-4 w-4" /> Solutions engineer notes
          </CardTitle>
        </CardHeader>
        <CardContent className="text-sm text-muted-foreground">
          Typical enterprise deployment: 2–4 weeks. Week 1 auth + feeds, Week 2 SOC + intel tuning,
          Week 3 API integrations, Week 4 executive reporting and handoff to customer SOC team.
        </CardContent>
      </Card>
    </div>
  );
}
